package com.pgigi.pumpkincampus.plugin.captcha

/**
 * 训练好的字符模板（与原始 MyCharacter 一致）。
 * 每个模板为 24 行 x 20 列，1 表示前景（黑），0 表示背景（白）。
 *
 * 模板数据以紧凑字符串形式存储，运行时解析为 IntArray，避免 JVM <clinit> 方法过大。
 *
 * 来源：Pumpkin-Toolkit `com.pgigi.pumpkintoolkit.qzrc.CharacterTemplates`
 * （原始项目 https://github.com/shuo747/QZRecognize ）。
 */
internal object CharacterTemplates {

    private const val LABELS_STR = "1,2,3,4,5,6,7,8,9,a,b,c,d,e,f,g,h,i,j,k,l,m,n,p,q,r,s,t,u,v,w,x,y,z"

    val labels: List<String> = LABELS_STR.split(",")

    private val rawTemplates: Array<String> = arrayOf(
        "",  // 1
        "",  // 2
        "",  // 3
        "",  // 4
        "",  // 5
        "",  // 6
        "",  // 7
        "",  // 8
        "",  // 9
        "",  // a
        "",  // b
        "",  // c
        "",  // d
        "",  // e
        "",  // f
        "",  // g
        "",  // h
        "",  // i
        "",  // j
        "",  // k
        "",  // l
        "",  // m
        "",  // n
        "",  // p
        "",  // q
        "",  // r
        "",  // s
        "",  // t
        "",  // u
        "",  // v
        "",  // w
        "",  // x
        "",  // y
        ""  // z
    )

    val templates: Array<Array<IntArray>> = Array(rawTemplates.size) { idx ->
        val raw = rawTemplates[idx]
        Array(24) { row ->
            IntArray(20) { col ->
                raw[row * 20 + col] - '0'
            }
        }
    }
}
